mkitem!{mkstruct!{#[doc = " An ordered map based on a [B-Tree]."] #[doc = ""] #[doc = " Given a key type with a [total order], an ordered map stores its entries in key order."] #[doc = " That means that keys must be of a type that implements the [`Ord`] trait,"] #[doc = " such that two keys can always be compared to determine their [`Ordering`]."] #[doc = " Examples of keys with a total order are strings with lexicographical order,"] #[doc = " and numbers with their natural order."] #[doc = ""] #[doc = " Iterators obtained from functions such as [`BTreeMap::iter`], [`BTreeMap::into_iter`], [`BTreeMap::values`], or"] #[doc = " [`BTreeMap::keys`] produce their items in key order, and take worst-case logarithmic and"] #[doc = " amortized constant time per item returned."] #[doc = ""] #[doc = " It is a logic error for a key to be modified in such a way that the key's ordering relative to"] #[doc = " any other key, as determined by the [`Ord`] trait, changes while it is in the map. This is"] #[doc = " normally only possible through [`Cell`], [`RefCell`], global state, I/O, or unsafe code."] #[doc = " The behavior resulting from such a logic error is not specified, but will be encapsulated to the"] #[doc = " `BTreeMap` that observed the logic error and not result in undefined behavior. This could"] #[doc = " include panics, incorrect results, aborts, memory leaks, and non-termination."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " use std::collections::BTreeMap;"] #[doc = ""] #[doc = " // type inference lets us omit an explicit type signature (which"] #[doc = " // would be `BTreeMap<&str, &str>` in this example)."] #[doc = " let mut movie_reviews = BTreeMap::new();"] #[doc = ""] #[doc = " // review some movies."] #[doc = " movie_reviews.insert(\"Office Space\",       \"Deals with real issues in the workplace.\");"] #[doc = " movie_reviews.insert(\"Pulp Fiction\",       \"Masterpiece.\");"] #[doc = " movie_reviews.insert(\"The Godfather\",      \"Very enjoyable.\");"] #[doc = " movie_reviews.insert(\"The Blues Brothers\", \"Eye lyked it a lot.\");"] #[doc = ""] #[doc = " // check for a specific one."] #[doc = " if !movie_reviews.contains_key(\"Les Misérables\") {"] #[doc = "     println!(\"We've got {} reviews, but Les Misérables ain't one.\","] #[doc = "              movie_reviews.len());"] #[doc = " }"] #[doc = ""] #[doc = " // oops, this review has a lot of spelling mistakes, let's delete it."] #[doc = " movie_reviews.remove(\"The Blues Brothers\");"] #[doc = ""] #[doc = " // look up the values associated with some keys."] #[doc = " let to_find = [\"Up!\", \"Office Space\"];"] #[doc = " for movie in &to_find {"] #[doc = "     match movie_reviews.get(movie) {"] #[doc = "        Some(review) => println!(\"{movie}: {review}\"),"] #[doc = "        None => println!(\"{movie} is unreviewed.\")"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " // Look up the value for a key (will panic if the key is not found)."] #[doc = " println!(\"Movie review: {}\", movie_reviews[\"Office Space\"]);"] #[doc = ""] #[doc = " // iterate over everything."] #[doc = " for (movie, review) in &movie_reviews {"] #[doc = "     println!(\"{movie}: \\\"{review}\\\"\");"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " A `BTreeMap` with a known list of items can be initialized from an array:"] #[doc = ""] #[doc = " ```"] #[doc = " use std::collections::BTreeMap;"] #[doc = ""] #[doc = " let solar_distance = BTreeMap::from(["] #[doc = "     (\"Mercury\", 0.4),"] #[doc = "     (\"Venus\", 0.7),"] #[doc = "     (\"Earth\", 1.0),"] #[doc = "     (\"Mars\", 1.5),"] #[doc = " ]);"] #[doc = " ```"] #[doc = ""] #[doc = " ## `Entry` API"] #[doc = ""] #[doc = " `BTreeMap` implements an [`Entry API`], which allows for complex"] #[doc = " methods of getting, setting, updating and removing keys and their values:"] #[doc = ""] #[doc = " [`Entry API`]: BTreeMap::entry"] #[doc = ""] #[doc = " ```"] #[doc = " use std::collections::BTreeMap;"] #[doc = ""] #[doc = " // type inference lets us omit an explicit type signature (which"] #[doc = " // would be `BTreeMap<&str, u8>` in this example)."] #[doc = " let mut player_stats = BTreeMap::new();"] #[doc = ""] #[doc = " fn random_stat_buff() -> u8 {"] #[doc = "     // could actually return some random value here - let's just return"] #[doc = "     // some fixed value for now"] #[doc = "     42"] #[doc = " }"] #[doc = ""] #[doc = " // insert a key only if it doesn't already exist"] #[doc = " player_stats.entry(\"health\").or_insert(100);"] #[doc = ""] #[doc = " // insert a key using a function that provides a new value only if it"] #[doc = " // doesn't already exist"] #[doc = " player_stats.entry(\"defence\").or_insert_with(random_stat_buff);"] #[doc = ""] #[doc = " // update a key, guarding against the key possibly not being set"] #[doc = " let stat = player_stats.entry(\"attack\").or_insert(100);"] #[doc = " *stat += random_stat_buff();"] #[doc = ""] #[doc = " // modify an entry before an insert with in-place mutation"] #[doc = " player_stats.entry(\"mana\").and_modify(|mana| *mana += 200).or_insert(100);"] #[doc = " ```"] #[doc = ""] #[doc = " # Background"] #[doc = ""] #[doc = " A B-tree is (like) a [binary search tree], but adapted to the natural granularity that modern"] #[doc = " machines like to consume data at. This means that each node contains an entire array of elements,"] #[doc = " instead of just a single element."] #[doc = ""] #[doc = " B-Trees represent a fundamental compromise between cache-efficiency and actually minimizing"] #[doc = " the amount of work performed in a search. In theory, a binary search tree (BST) is the optimal"] #[doc = " choice for a sorted map, as a perfectly balanced BST performs the theoretical minimum number of"] #[doc = " comparisons necessary to find an element (log<sub>2</sub>n). However, in practice the way this"] #[doc = " is done is *very* inefficient for modern computer architectures. In particular, every element"] #[doc = " is stored in its own individually heap-allocated node. This means that every single insertion"] #[doc = " triggers a heap-allocation, and every comparison is a potential cache-miss due to the indirection."] #[doc = " Since both heap-allocations and cache-misses are notably expensive in practice, we are forced to,"] #[doc = " at the very least, reconsider the BST strategy."] #[doc = ""] #[doc = " A B-Tree instead makes each node contain B-1 to 2B-1 elements in a contiguous array. By doing"] #[doc = " this, we reduce the number of allocations by a factor of B, and improve cache efficiency in"] #[doc = " searches. However, this does mean that searches will have to do *more* comparisons on average."] #[doc = " The precise number of comparisons depends on the node search strategy used. For optimal cache"] #[doc = " efficiency, one could search the nodes linearly. For optimal comparisons, one could search"] #[doc = " the node using binary search. As a compromise, one could also perform a linear search"] #[doc = " that initially only checks every i<sup>th</sup> element for some choice of i."] #[doc = ""] #[doc = " Currently, our implementation simply performs naive linear search. This provides excellent"] #[doc = " performance on *small* nodes of elements which are cheap to compare. However in the future we"] #[doc = " would like to further explore choosing the optimal search strategy based on the choice of B,"] #[doc = " and possibly other factors. Using linear search, searching for a random element is expected"] #[doc = " to take B * log(n) comparisons, which is generally worse than a BST. In practice,"] #[doc = " however, performance is excellent."] #[doc = ""] #[doc = " [B-Tree]: https://en.wikipedia.org/wiki/B-tree"] #[doc = " [binary search tree]: https://en.wikipedia.org/wiki/Binary_search_tree"] #[doc = " [total order]: https://en.wikipedia.org/wiki/Total_order"] #[doc = " [`Cell`]: core::cell::Cell"] #[doc = " [`RefCell`]: core::cell::RefCell"] #[stable (feature = "rust1" , since = "1.0.0")] #[cfg_attr (not (test) , rustc_diagnostic_item = "BTreeMap")] #[rustc_insignificant_dtor] pub struct BTreeMap < K , V , #[unstable (feature = "allocator_api" , issue = "32838")] A : Allocator + Clone = Global , > { root : Option < Root < K , V > > , length : usize , #[doc = " `ManuallyDrop` to control drop order (needs to be dropped after all the nodes)."] pub (super) alloc : ManuallyDrop < A > , _marker : PhantomData < crate :: boxed :: Box < (K , V) , A > > , }}}
